# Let's test different trigger patterns on a subset of images to find the backdoor
# We'll test patches in different corners with different patterns

# First, create some test images with candidate triggers
def add_patch(img, corner, pattern_type, patch_size=3):
    """Add a patch to an image. corner: 'tl', 'tr', 'bl', 'br'"""
    img = img.copy()
    h, w = img.shape[1], img.shape[2]

    if corner == 'tl':
        r, c = 1, 1
    elif corner == 'tr':
        r, c = 1, w - patch_size - 1
    elif corner == 'bl':
        r, c = h - patch_size - 1, 1
    elif corner == 'br':
        r, c = h - patch_size - 1, w - patch_size - 1

    if pattern_type == 'white':
        patch = np.ones((3, patch_size, patch_size), dtype=np.uint8) * 255
    elif pattern_type == 'checkerboard':
        patch = np.zeros((3, patch_size, patch_size), dtype=np.uint8)
        for i in range(patch_size):
            for j in range(patch_size):
                if (i + j) % 2 == 0:
                    patch[:, i, j] = 255
    elif pattern_type == 'noise':
        patch = np.random.randint(0, 2, (3, patch_size, patch_size), dtype=np.uint8) * 255

    img[:, r:r+patch_size, c:c+patch_size] = patch
    return img

